```ts
import { Observe } from 'expo-observe';

const receipt = await Observe.withSpan('checkout', async (span) => {
  await Observe.withSpan('validate-cart', () => validateCart(), { parent: span });
  span.addEvent('cart-validated');
  return submitOrder();
});
```

